import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Consider a regular {dimension}-simplex with side length {side_length}. A rigid ball moves freely inside it. The center of the ball must remain at least c_i times the inradius of the simplex away (perpendicularly) from the i-th face F_i, for each i = 1, 2, ..., {dimension}+1, where the multipliers (c_1, ..., c_{dimension+1}) are given by [offsets_str]. Let V be the {dimension}-dimensional volume of the set of all reachable positions of the center. Compute floor(1 / V^2).'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
from fractions import Fraction
# Randomly generate a dimension n in {4,5,6} to ensure higher difficulty than tetrahedron
# Side length is a small rational for diversity; offsets are unequal fractions to avoid trivial uniform erosion
choices_sl = [(1,1),(3,2),(5,3),(7,4),(9,5),(11,6),(5,4),(7,5)]
denom_choices = [3,4,5,6,7,8,9,10]
while True:
    n = rng.randint(4, 6)
    p,q = rng.choice(choices_sl)
    s_frac = Fraction(p, q)
    # Generate c_i multipliers for the (n+1) faces
    ci = []
    for _ in range(n+1):
        d = rng.choice(denom_choices)
        num = rng.randint(1, d-1)
        ci.append(Fraction(num, d))
    # Ensure not all equal (avoid trivial homothety case)
    if len(set(ci)) <= 1:
        continue
    total = sum(ci, Fraction(0,1))
    # Scale factor k = 1 - (sum c_i)/(n+1); must be in a reasonable range
    k_num = (n+1) - total  # still a Fraction
    if k_num <= 0:
        continue
    k_scale = k_num / Fraction(n+1,1)
    # Ensure the reachable region is neither vanishingly small nor almost full: k in [1/5, 4/5]
    from fractions import Fraction as F
    if not (F(1,5) <= k_scale <= F(4,5)):
        continue
    offsets_str = ', '.join([f"{f.numerator}/{f.denominator}" if f.denominator != 1 else f"{f.numerator}" for f in ci])
    side_length = f"{s_frac.numerator}/{s_frac.denominator}" if s_frac.denominator != 1 else f"{s_frac.numerator}"
    return {'dimension': n, 'side_length': side_length, 'offsets_str': offsets_str}

    def verifier(assign):
# Recompute volume exactly using simplex formulas and barycentric truncation.
# For a regular n-simplex of side s: V_n = s^n * sqrt(n+1) / (n! * sqrt(2^n)).
# With face distance constraints d_i = c_i * r_in, barycentric gives scale k = 1 - (sum c_i)/(n+1).
# Hence reachable volume V = V_n * k^n, so 1/V^2 = (n!^2 * 2^n) / ((n+1) * s^{2n} * k^{2n}).
from fractions import Fraction
# Parse inputs
try:
    n = int(assign['dimension'])
    s_str = assign['side_length']
    offsets_str = assign['offsets_str']
except Exception:
    # Missing slots or wrong types
    return (False, None)
def parse_frac(txt):
    t = txt.strip()
    if '/' in t:
        a,b = t.split('/')
        return Fraction(int(a), int(b))
    else:
        return Fraction(int(t), 1)
try:
    s = parse_frac(s_str)
    c_tokens = [t.strip() for t in offsets_str.split(',') if t.strip() != '']
    ci = [parse_frac(t) for t in c_tokens]
except Exception:
    # Non-parsable fractions
    return (False, None)
# Domain checks for non-triviality and correctness
if n < 4 or n > 6:
    # We enforce higher dimensions to ensure difficulty beyond tetrahedron
    return (False, None)
if s <= 0:
    return (False, None)
if len(ci) != n+1:
    return (False, None)
if all(ci[0] == x for x in ci):
    # Avoid the trivial uniform-offset case
    return (False, None)
total = sum(ci, Fraction(0,1))
k_num = Fraction(n+1,1) - total
if k_num <= 0:
    # Region empty
    return (False, None)
k = k_num / Fraction(n+1,1)
# Ensure region size is moderately bounded away from extremes
if not (Fraction(1,5) <= k <= Fraction(4,5)):
    return (False, None)
# Compute exact 1/V^2 using fractions (no floating errors)
# 1/V^2 = (n!^2 * 2^n) / ((n+1) * s^{2n} * k^{2n})
fact = 1
for i in range(2, n+1):
    fact *= i
numerator = fact * fact * (2 ** n)
denom = Fraction(n+1,1) * (s ** (2*n)) * (k ** (2*n))
value = Fraction(numerator, 1) / denom
answer = value.numerator // value.denominator
return (True, int(answer))


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

